INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_advertising','regulatory_pressure','Public debate on banning political advertising surfaces alongside developer activity for agency tooling','Public conversations about banning political advertising and the legality of advertising more broadly, visible in high-engagement Hacker News threads, coincide with public developer repositories that reference agency/market tooling; together these signals suggest increased scrutiny of ad content and practitioners building or sharing agency-oriented artifacts.','Two high-visibility Hacker News threads — ''Twitter to ban political advertising'' and ''What if we made advertising illegal?'' — show active public debate about restricting advertising, while recent public GitHub repositories with names referencing agencies and market tooling were pushed on the same snapshot of activity, indicating contemporaneous developer interest in advertising-related artifacts.','Global','Indonesia','Advertising','Advertising','agency tooling and content-compliance for contested ad categories','small','["smb", "mid_market", "enterprise", "developer"]','emerging','Build tools that help agencies and advertisers audit, classify, or route sensitive ad content to comply with emerging platform or regulatory restrictions and to document decisions for public scrutiny.','Evidence shows public debate (Hacker News) and public developer activity (GitHub repos); the link between the two is plausible but unverified — there is no registry evidence tying the repositories to specific agencies or to regulatory responses.','{"headline": "Compliance-first creative workflow for politically or legally sensitive campaigns", "wedge": "Ship an audit trail and content-classification plugin that integrates with agency campaign briefs and common design/deployment repositories developers already publish.", "icp": "Small-to-mid sized agencies and in-house marketing teams facing platform restrictions on political or sensitive advertising who also have developer resources or use public repositories for campaign assets.", "gtm": "Target agencies via developer-oriented channels (public repos, code examples) and industry forums where advertising policy debate occurs; offer pilot audits for campaigns in contested categories.", "moat": "A dataset of labeled campaign decisions and an auditable workflow that maps brief-to-delivery compliance could become a defensible asset if crowdsourced from agency pilots, though no such dataset is present in the supplied evidence.", "risks": "Evidence does not show actual regulatory changes or platform policy enforcement beyond public discussion; repositories may be generic templates unrelated to compliance and regional prominence in Indonesia among sample companies may not reflect where regulatory pressure will materialize."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,93,0,'["advertising-regulation", "agency-tools", "content-compliance", "developer-activity"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
