INSERT INTO signal_evidence (id,signal_id,kind,title,detail,source_key,url,weight,observed_at) VALUES ('be08814f-00b7-463a-9687-9a4b6fe234a9','sig_sector_analytics','discussion','Firebase Analytics SDK not detected on iOS unless I call Analytics.setAnalyticsCollectionEnabled(true)','Stack Overflow question · 1 answers · 102 views · last activity 2026-09-29','stackexchange_questions','https://stackoverflow.com/questions/79999012/firebase-analytics-sdk-not-detected-on-ios-unless-i-call-analytics-setanalyticsc',0.5,'2026-09-29T08:35:27.000Z');
INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_ar_vr','emerging_niche_demand','Developer tooling wedge in AR/VR experiences','Public developer activity and recent technical questions indicate a persistent, developer-led need for better AR/VR/XR tooling and content workflow support rather than pure consumer hardware demand. Evidence includes active public repositories with recent pushes, unanswered or recent Stack Overflow XR questions, and high-engagement Hacker News threads about AR/VR creation tools and device analysis.','Two public GitHub repositories show commits on 2026-09-30 and Stack Overflow/XR questions have activity as recently as 2026-09-29 and 2026-03-04, while high-engagement Hacker News threads discuss AR/VR creation platforms and device analysis, collectively signalling ongoing developer friction points for building XR experiences.','North America','United States','AR/VR','AR/VR','xr developer tooling for content & scene workflow','small','["developer", "enterprise", "consumer"]','emerging','Build focused tooling that reduces friction in XR scene composition, environment blending, and content lifecycle, targeted first at developers who currently rely on public repos and community Q&A for fixes and examples.','Evidence is based on public threads, registry records, and GitHub/Stack Overflow activity; there is no verified product usage, funding, or customer data in the supplied evidence, so validate demand with developer interviews and usage metrics before scaling.','{"headline": "A developer-first XR toolkit that makes scene transitions, environment blending, and multi-platform deployment predictable.", "wedge": "Start with solving a narrow, high-friction developer problem surfaced in Stack Overflow threads \u2014 for example, environment blend modes and scene loading \u2014 and ship battle-tested integrations for popular engines (Unity) and export pipelines.", "icp": "Small teams and studios building interactive XR experiences who currently search public repos and Stack Overflow for implementation details, and mid-market enterprises embedding XR demos that need reliable scene transitions and deployment scripts.", "gtm": "Community-led launch: tutorials addressing the specific Stack Overflow questions, sample repos on GitHub, and developer-focused threads on Hacker News to capture early adopters and contributors.", "moat": "Rich example libraries, engine-specific integrations, and an ecosystem of reproducible sample projects hosted in public repos that become de facto references for common XR problems.", "risks": "Evidence is limited to public registry entries, forum activity, and two public repositories; it does not confirm commercial demand, willingness to pay, or competitive incumbents solving the same developer problems."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,90,0,'["ar-vr", "xr-development", "developer-tools", "spatial-computing"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
