INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_autotech','workflow_digitization','Tools and workflows to bridge technician skill gap and repairability friction','Public developer activity (two public AutoTech repositories on GitHub) combined with active online discussion about over-engineered cars driving technicians away and ''right to repair'' claims indicates a near-term opportunity for software and workflow tooling that helps technicians diagnose, repair, and document modern vehicles more effectively.','Two Hacker News threads explicitly discuss technician attrition from ''over engineered cars'' and the contested ''right to repair'' narrative, and there are recent public AutoTech repositories on GitHub pushed as of 2026-09-30, showing both community concern and developer activity around AutoTech tooling.','Global','Germany','AutoTech','AutoTech','diagnostics, repair workflow and technician enablement software','small','["smb", "mid_market", "enterprise"]','emerging','Build focused tooling that reduces diagnostic complexity and records repair workflows to make modern vehicles serviceable for smaller garages and dealer networks; lean on developer community contributions visible in public repositories.','Evidence shows developer activity and public conversation, but does not prove customer willingness to pay or identify incumbent products; validate demand with shop-level interviews and pilots.','{"headline": "A lightweight diagnostics and repair-workflow platform for technicians stretched by complex vehicle systems.", "wedge": "Ship a free developer-friendly diagnostics SDK and a simple mobile repair checklist that captures steps and parts used, then convert high-usage shops to paid features.", "icp": "Independent and small-chain repair shops and mid-size dealer service operations frustrated by diagnostic complexity and paperwork overhead.", "gtm": "Start with developer and enthusiast channels (GitHub repo contributors and Hacker News communities cited), run pilots with local shops, then expand through partnerships with parts suppliers and training providers.", "moat": "Network effects from aggregated anonymized repair workflows and diagnostic signatures, plus integrations with common shop management systems; community contributions to diagnostic mappings from public repositories.", "risks": "Evidence does not include customer interviews, incumbent product mapping, or regulatory constraints; the ''right to repair'' debate could create legal or OEM access barriers that need direct verification."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,87,0,'["diagnostics", "repair-workflow", "right-to-repair", "developer-activity"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
