INSERT INTO signal_evidence (id,signal_id,kind,title,detail,source_key,url,weight,observed_at) VALUES ('6ad44819-78a1-43b6-9090-b26b661a10d1','sig_sector_chemicals','discussion','How do I get Python GEKKO chemical splitter unit operation to propagate mole fractions from input to output streams?','Stack Overflow question · 1 answers · 86 views · last activity 2026-08-15','stackexchange_questions','https://stackoverflow.com/questions/79985489/how-do-i-get-python-gekko-chemical-splitter-unit-operation-to-propagate-mole-fra',0.5,'2026-08-15T20:06:54.000Z');
