INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_climatetech_cleantech','category_creation','Registry labels show diverse companies mapped to ClimateTech taxonomy','Wikidata registry records in the sample classify companies from multiple countries and founding eras under the ClimateTech/CleanTech industry label, suggesting public data sources are already being used to tag a broad and heterogeneous set of companies to this sector.','The evidence consists of Wikidata records for Afriso-Euro-Index (Germany, founded 1869), Beneq (Finland, founded 2005) and Ecycler (United States, founded 2009) that carry an industry label mapping to ClimateTech/CleanTech, indicating active classification in public registries.','Global','Germany','ClimateTech/CleanTech','ClimateTech/CleanTech','public-registry-driven sector taxonomy','small','["enterprise", "government", "smb"]','emerging','Build tooling that ingests and normalizes public registry labels (Wikidata and similar) to create a cleaned, queryable ClimateTech taxonomy and to surface under-indexed legacy firms and recent entrants for research or deal-sourcing.','The supplied_taxonomy_count is a supplied discovery count and not independently verified; the sample evidence is limited to three Wikidata records and a broader mapping should be validated against more registry sources before scaling.','{"headline": "Normalize public registry industry labels into a usable ClimateTech taxonomy", "wedge": "Start with automated ingestion and deduplication of Wikidata industry labels for German and EU-registered firms, then expand to other registries to surface cross-listed entities and legacy incumbents.", "icp": "Research teams at VCs, corporate strategy groups, and market intelligence providers who need an auditable mapping of public-registry labels to a ClimateTech taxonomy.", "gtm": "Offer an initial product as a curated dataset plus a search API and CSV exports to researchers and investors, leveraging examples from Wikidata to demonstrate provenance.", "moat": "Provenance-first dataset of cleaned registry mappings and entity deduplication logic that links public labels to canonical company records.", "risks": "Evidence is limited to a small set of Wikidata records; public registries can be inconsistent in labeling and completeness, and mapping errors could propagate if source coverage is not broadened and validated."}','{"growth_direction": "steady", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',55,100,0,'["taxonomy", "public-registries", "climatetech", "data-infrastructure"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
