INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_deeptech','category_creation','DeepTech label surfaces across incumbents and active developer projects','Registry records map a mix of long-established engineering firms and newer firms into a DeepTech sector label, while public developer repositories and Hacker News threads show active community discussion and recent code activity tied to the label. This pattern suggests DeepTech is being used as a cross-cutting taxonomy that spans established industrial engineering firms and an active developer community building public artifacts.','Multiple Wikidata records in the evidence set explicitly map companies such as Aker Solutions, Alten and Bechtel to the DeepTech industry label, Hacker News threads discuss DeepTech topics (including moats and a Berlin landscape), and two public GitHub repositories were pushed on 2026-09-30, indicating recent developer activity associated with the label.','Europe','United States','DeepTech','DeepTech','taxonomized incumbents + public developer signal','large','["enterprise", "government", "developer"]','scaling','Build tooling and data products that standardize how DeepTech is described and discovered (taxonomies, registries, project indices) to help buyers and builders reconcile large incumbents and smaller developer-led projects.','Treat the supplied_taxonomy_count of 828 as an unverified discovery count; verify the underlying taxonomy and expand company sampling beyond the 12 recorded to confirm breadth and activity across regions.','{"headline": "Developer-forward DeepTech registry that links public repos, community discussions, and corporate metadata.", "wedge": "Start with automated ingestion of Wikidata industry labels and GitHub activity to create searchable profiles that surface both incumbents and recent code pushes.", "icp": "Procurement teams and R&D groups at large engineering firms and government agencies, plus developer communities organizing around deeptech projects.", "gtm": "Outreach to engineering procurement and R&D lists using case studies that show how the registry reduces discovery friction; partner with community hubs where Hacker News-style discussions occur to seed developer contributions.", "moat": "Proprietary mappings between registry entries and developer activity, sustained curation workflows, and integrations into enterprise procurement or R&D tooling.", "risks": "Evidence is limited to a small recorded company sample and public signals; the supplied taxonomy count (828) is unverified, and it is not established which subset of the taxonomy has commercial demand or active projects beyond the repositories and threads cited."}','{"growth_direction": "steady", "cap_band_spread": ["large", "micro"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',78,91,0,'["deeptech-taxonomy", "developer-signal", "registry", "enterprise-discovery"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
