INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_direct_to_consumer_dtc','workflow_digitization','Marketing analytics dashboards emerging as a DTC tooling wedge','Public developer activity and discussion indicate a narrow engineering wedge: teams building campaign performance dashboards and analytics tooling aimed at Direct-to-Consumer brands. Wikidata records for legacy consumer brands mapped to the DTC sector show this is an established label across large incumbents, while recent public repos and forum threads show ongoing grassroots engineering and product conversations focused on DTC marketing workflows.','Two public GitHub repositories with recent pushes (one explicitly named ''Direct-To-Consumer-Campaign-performance-dashboard'', last pushed 2026-09-30) and an active Launch HN thread about a DTC-facing insurance product signal fresh engineering and product interest; this is supported by a Stack Overflow thread showing related frontend build activity. What remains unverified from this evidence is commercial adoption, customer traction, and whether these projects are prototypes or production tools.','Global','Indonesia','Direct-to-Consumer (DTC)','Direct-to-Consumer (DTC)','campaign performance dashboards for DTC brands','small','["smb", "mid_market", "enterprise"]','emerging','Build a focused analytics dashboard product that integrates advertising and on-site performance metrics for DTC brands, addressing the engineering gap signaled by public repos and developer questions.','Evidence is primarily public developer activity and registry labels; validate demand with customer interviews and by assessing whether the GitHub projects are internal prototypes or intended for end users.','{"headline": "Launch a lightweight, plug-and-play campaign performance dashboard tailored to DTC marketing teams.", "wedge": "Ship connectors and prebuilt dashboards for common DTC ad channels and ecommerce platforms to accelerate time-to-insight for small marketing teams.", "icp": "Small to mid-market DTC ecommerce brands that run multi-channel paid campaigns and lack centralized analytics tooling.", "gtm": "Start with developer-friendly onboarding and open-source reference dashboards to attract engineering attention, then convert via templates and paid connectors.", "moat": "Productized integrations to ad platforms and ecommerce stacks plus prebuilt, DTC-specific KPIs and templates that reduce setup time compared with general BI tools.", "risks": "Public repos may be prototypes without commercial intent, and registry labels mapping legacy brands to DTC do not prove demand for new tooling; competition from general BI and agency-built solutions is also unverified."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',79,94,0,'["dtc-marketing", "marketing-analytics", "developer-tools", "campaign-dashboard"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
