INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_drug_delivery','emerging_niche_demand','Early public interest and developer activity around implantable ocular drug reservoirs within the broader drug-delivery sector','Wikidata records map major pharmaceutical companies to the Drug Delivery sector while recent public discussion and code activity show specific interest in implantable ocular micro-reservoir concepts and related drug-delivery projects; this suggests a discernible niche interest inside a large incumbent-led sector rather than a proven commercial market yet.','Evidence includes multiple Wikidata registry records that label established pharmas (examples: AstraZeneca, BioNTech, Eli Lilly) under Drug Delivery, a Hacker News thread explicitly about self-implantable double-layered micro-drug-reservoirs for ocular delivery, and public GitHub repositories with ''drug-delivery'' related code activity; together these signals point to concurrent technical discussion and prototyping alongside established industry classification.','Global','United States','Drug Delivery','Drug Delivery','implantable ocular micro-drug-reservoirs','large','["enterprise", "mid_market", "developer"]','emerging','Founders can focus on translating public prototyping and academic interest in implantable ocular reservoirs into regulated pilots with clinical partners, addressing refillability and sustained-release control that are being discussed in public threads and repos.','The evidence set includes registry records, public discussion threads, and GitHub repos but lacks clinical trial data, regulatory filings, customer pilots, or verified commercialization activity; those items should be validated before sizing opportunity or fundraising.','{"headline": "Prototype refillable ocular micro-reservoirs and secure pilot collaborations with ophthalmology research centers.", "wedge": "Ship a clinician-facing, refillable ocular implant design with reproducible release kinetics and open-source preclinical protocols to accelerate academic pilot adoption (supported by public discussion and repo activity).", "icp": "Ophthalmology research groups, biotech product teams inside mid-to-large pharma, and clinical trial teams at academic medical centers interested in sustained intraocular drug delivery.", "gtm": "Publish reproducible preclinical methods, run co-development pilots with academic ophthalmology centers, and use developer-oriented repos and community threads to attract early research collaborators.", "moat": "Clinical safety and efficacy data, device-specific IP, and regulatory approvals combined with early clinical partnerships that move prototypes out of public discussion into validated pilots.", "risks": "Primary risks are unverified clinical feasibility and regulatory pathway, absence of commercialization evidence in the supplied sources, and safety/biocompatibility challenges not addressed by the current public threads or repos."}','{"growth_direction": "steady", "cap_band_spread": ["large", "micro"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',76,86,0,'["drug-delivery", "ocular-implants", "pharma-partnerships", "developer-activity"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opport