INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_food_and_beverage','underserved_segment','Surge in cargo theft focused on food & beverage freight creates a niche for logistics security','Public discussion threads report a recent surge in cargo theft led by food and beverage freight, indicating a near-term demand signal for security, monitoring, and loss-mitigation solutions tailored to F&B logistics.','Two separate Hacker News threads cite cargo theft rising and explicitly say food and beverage freight is leading the spike, with one thread referencing a 68% increase in a quarter; these public discussions point to elevated risk visibility for F&B shipments now.','Global','United States','Food and Beverage','Food and Beverage','security and loss-mitigation for food & beverage freight','large','["mid_market", "enterprise"]','emerging','Build monitoring, physical-security, or insurance-adjacent products focused on reducing theft and losses in F&B freight; validate which freight types and routes are most affected before scaling.','Evidence comes from public discussion threads; verify claimed theft rates with primary industry or law-enforcement data and identify whether refrigerated/perishable shipments are disproportionately impacted.','{"headline": "Supply-chain security for food freight: telematics, tamper detection, and loss workflows for F&B shippers and carriers.", "wedge": "Start with a single high-risk route or perishable category where theft is reported, using documented incident lists to pilot monitoring and response integrations with carriers.", "icp": "Large food manufacturers and national carriers responsible for long-haul F&B freight where public discussion indicates theft concentration.", "gtm": "Pilot with enterprise shippers on high-risk lanes, document prevented-loss cases, and sell into broader fleets and insurers once validation is achieved.", "moat": "Operational data on theft incidents and proven lane-level reduction in losses; partnerships with carriers and insurers to create preferred-provider status.", "risks": "Signal is based on public discussion threads rather than primary industry reports; the geographic concentration and permanence of the theft spike are unverified and must be confirmed."}','{"growth_direction": "accelerating", "cap_band_spread": ["large", "micro"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',76,87,0,'["supply-chain", "cargo-theft", "food-logistics", "security"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
