INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_games','underserved_segment','Active hobbyist and retro-console developer wedge within games','The recorded sample is dominated by legacy Japanese games incumbents while public discussions and developer activity show active hobbyist interest in retro consoles and game development tooling; this suggests a wedge for startups selling tooling or platforms aimed at retro/hobbyist game creators and consumers.','A high-engagement Hacker News thread titled ''Show HN: A retro video game console I''ve been working on in my free time'' and recent GitHub pushes (repositories with last push 2026-09-30) indicate current, visible community momentum among hobbyist creators, and an active Stack Overflow question about HTA for game development shows ongoing demand for beginner/intermediate developer help.','Global','Japan','Games','Games','tools and platforms for retro/hobbyist game creators','large','["consumer", "developer"]','established','Build focused tooling, distribution, or hardware kits that lower the barrier for hobbyist retro-console projects and small creator game experiments, targeting engaged online communities visible on Hacker News, GitHub, and Stack Overflow.','Supplied discovery count is 469 (unverified); recorded sample includes multiple long-established Japanese firms (Capcom, Konami, Nintendo, Sony Group, Panasonic Holdings Corporation) per Wikidata records, and public developer/discussion activity dated 2026-09-30 provides evidence of active hobbyist and developer interest. What remains unverified is the size and willingness-to-pay of the hobbyist segment and whether the recorded incumbent companies are addressing this wedge.','{"headline": "Developer-first retro console SDK and community hub for hobby creators", "wedge": "Starter kits and SDK tailored for retro-style hardware projects promoted through high-engagement HN threads and GitHub repos where hobbyist projects are already visible.", "icp": "Individual hobbyist developers and small creator teams active on Hacker News, GitHub, and Stack Overflow who build retro-console projects or small indie games.", "gtm": "Engage via developer communities (HN, GitHub), publish example projects and tutorials (HTA/game dev walkthroughs), and seed early adopters with low-cost hardware kits and clear docs.", "moat": "Community and tooling lock-in from curated tutorials, example repos, and an active hub for sharing retro console projects; potential partnerships with creator influencers on HN/GitHub.", "risks": "Recorded evidence is selective: registries show large incumbents but do not indicate their product focus; community signals confirm hobbyist activity but do not quantify demand or willingness-to-pay."}','{"growth_direction": "steady", "cap_band_spread": ["large", "micro"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,93,0,'["games", "retro-gaming", "developer-tools", "japan", "consumer-games"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
