INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_gaming_esports','emerging_niche_demand','Developer-driven analytics and light game tooling activity in eSports','Public developer activity and community discussions point to an active, grassroots build layer for eSports analytics and light game projects; this suggests founders can wedge into tooling for match/score analytics, visualization, and small-scale eSports titles or idle experiences.','Two public GitHub repositories related to e-sports and game analytics were pushed on 2026-09-30, and multiple Stack Overflow questions about charting and saving visualizations tied to game/analytics use cases have recent activity (2025). Registry records for companies across regions (including Japan and Denmark) and Hacker News threads discussing e-sports topics indicate ongoing community and industry attention.','Global','Japan','Gaming/eSports','Gaming/eSports','developer-facing analytics and visualization for eSports','small','["smb", "mid_market", "developer"]','scaling','Ship developer-focused analytics primitives (match-level scorigami, live chart exports, lightweight telemetry ingestion) that integrate into tournament platforms and community sites to capture DIY tooling demand evident in public repos and forum questions.','Evidence is developer- and community-facing: public GitHub activity and forum threads show technical interest, but there is limited verified evidence here about commercial adoption, paying customers, or enterprise integration.','{"headline": "Turn public prototypes into a small, documented analytics SDK and hosted chart export service for tournament organizers and community platforms.", "wedge": "Start with a narrow SDK for one popular title''s match-level metrics (demonstrated by the LoL-Scorigami repo) and provide turnkey chart export/embedding (addresses Stack Overflow charting pain).", "icp": "Independent tournament organizers, community match sites, and small eSports publishers that need embeddable visualizations and simple match analytics without building backend telemetry stacks.", "gtm": "Leverage existing open-source demos and community threads to seed adoption: convert repo examples into quickstart templates, promote in relevant Hacker News and Stack Overflow discussions, and offer a free hosted tier for community operators.", "moat": "Productize integrations and curated match analytics templates for specific titles plus easy-to-install embed/export flows; community contributors and title-specific templates create switching costs.", "risks": "Current evidence is primarily public code and forum signals; commercial demand, willingness to pay, and enterprise-level requirements are unverified and would need validation with paying customers."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,87,0,'["esports", "developer-tools", "analytics", "gaming-data"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
