INSERT INTO signal_evidence (id,signal_id,kind,title,detail,source_key,url,weight,observed_at) VALUES ('ff1b7b78-fc1a-4f0d-9ae0-4e089e5b6e13','sig_sector_health_it','discussion','EC2 instance attached to a load balancer is showing Unhealthy status','Stack Overflow question · 6 answers · 86547 views · last activity 2026-09-29','stackexchange_questions','https://stackoverflow.com/questions/47766584/ec2-instance-attached-to-a-load-balancer-is-showing-unhealthy-status',0.5,'2026-09-29T16:48:25.000Z');
INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_human_capital_hrtech','workflow_digitization','Digitization wedge: incumbent staffing and recruitment firms mapped to HRTech','Registry records in the supplied taxonomy map both long-established staffing/recruitment firms and newer HR technology companies to the Human Capital/HRTech sector, indicating a wedge for software and workflow digitization targeted at incumbent people‑services providers.','Wikidata registry entries in the evidence set label companies founded across multiple decades (for example Airswift 1979, Empresaria Group 1996, Carlisle Managed Solutions 1997) with the Human Capital/HRTech industry tag; the recorded company sample also includes newer HRTech entrants such as HackerRank (founded 2012), suggesting coexistence of legacy firms and newer tech players in the same taxonomy. The supplied discovery count is large (a supplied discovery count of 352), but that figure is unverified by primary records in the evidence list.','Europe','United States','Human Capital/HRTech','Human Capital/HRTech','digitizing incumbent staffing and recruitment firms','mid','["smb", "mid_market", "enterprise"]','scaling','Build HR workflow products that integrate with or replace manual processes used by incumbent staffing and recruitment firms, focusing on migration paths for organizations founded before widespread HR SaaS adoption.','Evidence is based on Wikidata registry labels and a recorded sample of companies; the signal that incumbents and newer HRTech players coexist in the taxonomy is supported by those records, but additional primary research (customer interviews, product usage data) is needed to verify specific product gaps and willingness to adopt.','{"headline": "A SaaS onboarding and placement workflow tailored to legacy staffing firms.", "wedge": "Start with compliance and credential tracking modules for long-established staffing firms that currently rely on spreadsheets and disparate systems.", "icp": "Regional staffing and recruitment firms with legacy operations (examples in the recorded sample include companies founded in the 1970s\u20131990s) seeking to reduce manual processes.", "gtm": "Field sales plus industry trade channels that sell into staffing associations and niche recruitment verticals; pilot with firms in the recorded sample regions (United States and Europe).", "moat": "Deep integrations with applicant tracking systems and placement workflows used by incumbents, plus compliance and credential databases specific to staffing verticals.", "risks": "Evidence is limited to registry labels and a small recorded sample; it is unverified whether the listed organizations are actively seeking or adopting new HR software and what incumbent workflows look like today."}','{"growth_direction": "steady", "cap_band_spread": ["micro", "mid"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',55,100,0,'["hrtech", "staffing-digitization", "workflow-automation"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_a