INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_legaltech','vertical_software','Developer and open-source activity signals tooling focus within LegalTech','Public registries map multiple firms to LegalTech and recent public developer activity (two GitHub repositories with last pushes on 2026-09-30) plus community discussions on Hacker News indicate active developer and community interest in building LegalTech tooling and automation. This combination points to a practitioner- and developer-driven wedge inside LegalTech rather than purely legacy practice-management software.','Two public GitHub repositories show recent commits as of 2026-09-30, and Hacker News threads discuss LegalTech use cases and startups, suggesting fresh engineering and community attention; registry entries in Wikidata confirm a set of companies classified in the LegalTech sector. The evidence shows current code activity and public conversations, not verified commercial traction or funding events.','North America','United States','LegalTech','LegalTech','developer-focused legal document automation tooling','small','["developer", "smb", "mid_market", "enterprise"]','scaling','Build open-source-first developer tooling that integrates with common frontend stacks and legal document workflows, capturing interest shown by recent repo activity and public discussions; verify demand with developer surveys and pilot integrations before scaling.','Evidence is technical and community-oriented (GitHub pushes, HN threads, Wikidata classification). Commercial demand, revenue models, and customer willingness to pay are not established in the provided evidence and should be validated privately.','{"headline": "Open-source-first SDK and hosted orchestration for legal document automation that targets frontend developer workflows.", "wedge": "Ship an SDK that plugs into Next/React frontends and a hosted orchestration layer for document templates and variable injection, matching signals from a Stack Overflow question about inserting variables in frontend markdown and the observed repos.", "icp": "Small law firms and in-house legal teams that embed legal forms into customer-facing web flows, plus developer-led teams at mid-market companies needing document automation.", "gtm": "Start with developer outreach: example repos, templates, and integrations for popular stacks; surface use cases from community threads and convert early adopters via tutorials and open-source licensing that funnels to hosted premium features.", "moat": "Developer momentum and a library of pre-built, battle-tested templates and integrations for popular frontend stacks; open-source community contributions to sustain growth. Note: sustained moat depends on adoption and ecosystem lock-in, which are not evidenced here.", "risks": "Available evidence is limited to public registries, two active GitHub repositories, and a few community threads; there is no verified commercial traction, pricing data, or customer commitments in the supplied evidence, so product-market fit and willingness to pay remain unverified."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,87,0,'["legaltech", "developer-tooling", "document-automation", "open-source"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
