INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_marketingtech','emerging_niche_demand','Developer-first, code-driven video tooling as a marketing-tech wedge','Public developer activity and a high-profile Hacker News thread indicate growing interest in code-first video tools for marketing workflows; this suggests a niche opportunity for marketing‑tech products that treat video creation as programmable infrastructure rather than pure creative tooling.','A Hacker News thread titled ''Show HN: Revideo – Create Videos with Code'' attracted sustained attention, and multiple public GitHub repositories referencing ''marketingtech'' were recently active, signaling developer experimentation with marketing-focused code assets. These items together provide direct evidence of developer interest in programmatic video/marketing tooling right now.','Global','Japan','MarketingTech','MarketingTech','code-first video tooling for marketing workflows','micro','["developer", "smb", "mid_market", "enterprise"]','emerging','Build a developer-centric SDK/API and accompanying templates that let marketing teams automate short-form campaign video generation; pair the API with integrations into common marketing stacks to lower adoption friction for non-developer users.','Evidence is limited to a Hacker News product thread and public GitHub activity; broader demand from CMOs or ad agencies in the recorded company sample is not demonstrated by the provided evidence and should be validated with customer conversations.','{"headline": "Offer an API-first video generation platform with marketing templates and SaaS orchestration for campaign workflows.", "wedge": "Start with developer ergonomics and reproducible templates (code snippets + SDK) that developers can embed into CI or campaign automation, then surface simple UI flows for marketers.", "icp": "Marketing teams at developer-forward companies and agencies that already automate campaign distribution, plus developer-led SMBs needing repeatable short-form video assets.", "gtm": "Seed adoption via developer outreach (OSS SDK, GitHub examples), showcase HN-style demos, and pilot integrations with popular marketing automation platforms to prove workflow value to non-developer users.", "moat": "Move from demos to a library of validated, reusable campaign templates and tight integrations that create switching friction for teams that automate video generation into their release pipelines.", "risks": "Existing agency incumbents in the recorded sample are not shown to endorse programmatic video; evidence is currently limited to developer discussions and public repos, so demand from traditional marketers remains unverified."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,86,0,'["video-automation", "developer-tools", "marketing-automation", "api-first"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
