INSERT INTO signal_evidence (id,signal_id,kind,title,detail,source_key,url,weight,observed_at) VALUES ('9b58fba0-a25d-4116-bd42-bf2dcffc9c8b','sig_sector_marketplaces','discussion','VSCodium remotely flags a locally installed .VSIX as &quot;problematic&quot; and automatically uninstalls it','Stack Overflow question · 1 answers · 152 views · last activity 2026-09-22','stackexchange_questions','https://stackoverflow.com/questions/79971624/vscodium-remotely-flags-a-locally-installed-vsix-as-problematic-and-automatic',0.5,'2026-09-22T06:23:15.000Z');
INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_material_science','emerging_niche_demand','Growing demand for AI-produced crystal-structure datasets and accessible tooling for materials R&D','Public discussion of a DeepMind result cataloguing millions of crystal structures, together with recent public Jupyter repositories active in 2026 and a small but global set of registered material-science companies, point to a demand wedge: researchers and developer teams want AI-generated crystal-structure data and reproducible notebooks to accelerate materials discovery workflows.','A Hacker News thread discusses a DeepMind output of 2.2M crystal structures, and two public GitHub repositories with Jupyter notebooks were pushed as recently as 2026-09-30, indicating contemporaneous interest and developer activity around computational materials tools; Wikidata records in the supplied company sample map multiple organizations to the material-science sector, supporting that there is an existing user base.','Global','United States','Material Science','Material Science','ai-generated crystal-structure datasets and reproducible notebooks for materials R&D','small','["developer", "mid_market", "enterprise", "government"]','emerging','Package AI-derived crystal-structure datasets with curated, reproducible notebooks and APIs that integrate into lab and simulation workflows to lower friction for materials teams and computational researchers.','The DeepMind result is represented by a public Hacker News discussion thread, not an official filing; repository activity shows developer interest but does not quantify adoption. The supplied_taxonomy_count is a provided discovery count and has not been independently verified.','{"headline": "Dataset + notebook product that makes AI-derived crystal structures immediately usable for simulation and screening.", "wedge": "Start with curated, validated subsets of AI-generated crystal structures and companion Jupyter notebooks tailored to a specific materials class to capture early research teams.", "icp": "Computational materials researchers at mid-market labs, enterprise R&D groups, and government research units that run simulations and need curated structure inputs and reproducible workflows.", "gtm": "Leverage reproducible notebooks and example pipelines to land pilot projects with academic labs and government research groups, then expand through partnerships with simulation software vendors and enterprise R&D teams.", "moat": "Proprietary curation and validation workflows for AI-generated structures, plus deep integration templates for common simulation tools and documented reproducible notebooks that reduce time-to-results.", "risks": "Evidence of demand rests on a public discussion thread and recent repository pushes; there is no provided evidence of commercial adoption, pricing tolerance, or regulatory constraints in the supplied materials."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,87,0,'["ai-materials", "crystal-datasets", "research-software", "computational-materials"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
