INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_semiconductors','geographic_expansion','Renewed push to build fabs in Europe and by new entrants','Public discussion threads show coordinated plans among established firms to build a semiconductor fab in Europe and separate threads report founders launching new fab efforts, indicating renewed geographic expansion and decentralization of manufacturing activity.','A Hacker News thread titled "TSMC, Bosch, Infineon, NXP to jointly build semiconductor fab in Europe" and a separate Hacker News thread titled "Sam Zeloof and Jim Keller start a new semiconductor fab" surfaced significant community attention, suggesting interest in both consortium-led European capacity and founder-led fab projects at the same time.','Global','United States','Semiconductors','Semiconductors','boutique and regional semiconductor fabs (Europe and founder-led builds)','mid','["enterprise", "government", "developer"]','scaling','Provide localized fabrication services, equipment, or supply-chain integration focused on European fab projects and small-scale founder fabs; adjacent software and tooling for boutique fabs may be an entry wedge.','Evidence is drawn from public discussion threads (Hacker News). These threads reflect community attention but are not primary confirmations of formal deals; other evidence items are developer repositories and Stack Overflow questions that indicate active engineering work but do not verify transactions. The supplied discovery count is 154 (supplied taxonomy count).','{"headline": "Platform tooling and supply-chain services for regional and boutique fabs", "wedge": "Target tooling for yield management and equipment orchestration tailored to small-to-mid-size fabs that cannot absorb commodity tools built for hyperscale fabs.", "icp": "Newly announced regional fabs, university spin-outs, and founder-led boutique fabs in Europe; government-backed fab initiatives.", "gtm": "Engage via pilot projects with engineering teams at announced fab initiatives, partner with equipment vendors and regional governments, and publish reproducible engineering case studies to build credibility.", "moat": "Domain expertise in fab operations for small-scale fabs, integrations with equipment vendors, and curated regional regulatory and supplier relationships that are costly to replicate.", "risks": "Primary evidence comes from public discussion threads rather than official filings or press releases; plans discussed may not materialize, and large incumbents could scale similar solutions if initiatives proceed."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "mid"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',76,87,0,'["regional-fabs", "fab-software", "europe-semi"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
