INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_smart_cities_urbantech','workflow_digitization','Registry labels reveal a cross‑generational Smart Cities/UrbanTech universe','Wikidata industry labels already map companies of very different ages and geographies into a single Smart Cities/UrbanTech category, indicating the sector in registries spans legacy engineering firms and recent entrants rather than being limited to purely new startups.','Three separate Wikidata records in the sample (Atkins 1938, Architecna 1980, African Urban Associates 2020) are labeled under the Smart Cities/UrbanTech industry in the registry, showing that public knowledge bases are consolidating diverse firms under this sector; the supplied discovery count is 100 (unverified) which suggests a larger tagged set in the taxonomy provided for review.','Global','United Kingdom','Smart Cities/UrbanTech','Smart Cities/UrbanTech','registry-driven sector taxonomy normalization','small','["government", "enterprise"]','established','Build tooling and workflows that deduplicate and normalize registry/knowledgebase labels so investors and buyers can distinguish legacy infrastructure engineering firms from recent digital-first Smart Cities entrants.','The evidence is limited to registry labels on three Wikidata records; it is unverified whether the broader set of companies in the supplied taxonomy share the same business models, customers, or technology stacks.','{"headline": "Normalize public registry tags to create a clean investable Smart Cities company list.", "wedge": "Start with automated reconciliation of Wikidata industry labels against firm founding year and country to surface cohorts (legacy engineering vs recent entrants).", "icp": "Procurement teams in city governments and institutional investors who rely on shortlists derived from public registries and taxonomies.", "gtm": "Offer a free registry-cleaning report for a sample region or city to demonstrate how mislabeled or conflated entries affect shortlists, then convert to subscription for ongoing updates.", "moat": "Proprietary mappings and heuristics for reconciling registry labels with firm attributes (founding year, corporate lineage) plus curated exclusions to reduce false positives.", "risks": "Registry labels are noisy and incomplete; relying on them without primary validation will surface false positives and miss unlisted entrants."}','{"growth_direction": "steady", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',55,100,0,'["registry-normalization", "smart-cities", "urbantech", "data-quality"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
