INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_social_networks','emerging_niche_demand','Resurgence of interest in off-grid / alternative social networks','Public discussion and developer activity indicate renewed interest in social-network alternatives focused on off-grid or non-mainstream models; Hacker News threads with high engagement discuss off-grid networks and a VC-funded attempt to replicate an independent social product, while recent public GitHub repositories show active development related to the space.','Two highly upvoted Hacker News threads (one titled ''An off-grid social network'' and another about a startup ''trying to steal my social network'') show strong community attention, and multiple public GitHub repositories were pushed recently (last pushed 2026-09-30), suggesting active experimentation among developers; Stack Overflow threads with recent activity show developer troubleshooting consistent with ongoing implementation work.','Global','United States','Social Networks','Social Networks','off-grid / alternative social networks','small','["consumer", "developer", "smb"]','emerging','Build lightweight, privacy- and connectivity-tolerant social products that appeal to communities discussing off-grid and independent social networks and provide tooling that reduces integration and deployment friction for developers.','Evidence is primarily discussion threads and public repositories; verify product-market fit and whether the GitHub activity maps to deployable projects or prototypes before prioritizing investment.','{"headline": "Ship an opinionated, easy-to-deploy social stack tailored for low-connectivity and community-run instances.", "wedge": "Provide a one-command deploy and bundled moderation/identity primitives that let small communities self-host without deep ops expertise.", "icp": "Community organizers and niche hobbyist groups seeking autonomous, privacy-focused spaces, plus developer-led SMBs wanting control over social features.", "gtm": "Engage Hacker News and developer communities with technical writeups and reproducible demos; convert early adopters from public threads and GitHub projects into reference deployments.", "moat": "Community-driven network effects from interoperable, open tooling and a library of prebuilt integrations for common self-hosting platforms.", "risks": "Current evidence does not confirm commercial demand or sustainable user growth; discussion and code activity may reflect hobbyist interest rather than scalable product adoption."}','{"growth_direction": "accelerating", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',77,91,0,'["decentralized-social", "self-hosting", "developer-tools"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
