INSERT INTO signals (id,type,title,thesis,why_now,region,country,sector,industry,niche,market_cap_band,target_customers,maturity_stage,founder_opportunity,advisor_note,build_opportunity,market_context,confidence_score,freshness_score,rank_score,tags,status,created_at,updated_at) VALUES ('sig_sector_transportationtech','category_creation','TransportationTech taxonomy signal — registry labels show cross-era, cross-country coverage','Public registry records (Wikidata) for multiple companies across different founding decades and countries are labeled with the TransportationTech industry, indicating the sector taxonomy maps to both legacy and modern transportation firms in the recorded universe of 12 companies.','Wikidata registry entries for Airstream (United States, founded 1931), DiDi (People''s Republic of China, founded 2012), and Garuda Indonesia (Indonesia, founded 1947) all carry an industry label that maps to TransportationTech, suggesting recent or existing curation of industry tags in public registries that surface this sector classification.','Global','United States','TransportationTech','TransportationTech','registry-driven transportation taxonomy curation','small','["enterprise", "government", "smb"]','established','Build tooling or services that aggregate, validate, and normalize public registry industry labels for TransportationTech companies to support research desks, procurement teams, and platform catalogues that need consistent sector classification.','Evidence is three Wikidata registry records and a recorded_company_total of 12; the supplied taxonomy count (657) is an unverified discovery count and should be treated as such. Broader claims about market demand, company counts beyond the recorded total, or commercial traction are unverified by the provided evidence.','{"headline": "Normalize public registry industry labels into a single TransportationTech taxonomy feed.", "wedge": "Start with deterministic mappings from Wikidata industry labels for the recorded sample and expand coverage by adding rule-based reconciliation for divergent labels.", "icp": "Data teams at research desks, government transport planners, and enterprise procurement teams that need a normalized list of TransportationTech companies across regions.", "gtm": "Pilot with research/analytics teams using the provided registry records as a proof-of-concept dataset, emphasize provenance from public registries (Wikidata).", "moat": "Curated mappings and provenance tracking for industry labels combined with a repeatable reconciliation process anchored to public registries.", "risks": "The evidence set is limited to three Wikidata records and a recorded sample of 12 companies; registry labels can be incomplete or inconsistent and the supplied taxonomy count is unverified."}','{"growth_direction": "steady", "cap_band_spread": ["micro", "small"], "tam_note": "Not recorded. The sector count shown on the markets page is a supplied discovery count, not TAM."}',55,100,0,'["transportation-tech", "data-taxonomy", "registry", "company-classification"]','active',datetime('now'),datetime('now')) ON CONFLICT(id) DO UPDATE SET type=excluded.type, title=excluded.title, thesis=excluded.thesis, why_now=excluded.why_now, region=excluded.region, country=excluded.country, sector=excluded.sector, industry=excluded.industry, niche=excluded.niche, market_cap_band=excluded.market_cap_band, target_customers=excluded.target_customers, maturity_stage=excluded.maturity_stage, founder_opportunity=excluded.founder_opportunity, advisor_note=excluded.advisor_note, build_opportunity=excluded.build_opportunity, market_context=excluded.market_context, confidence_score=excluded.confidence_score, freshness_score=excluded.freshness_score, tags=excluded.tags, status='active', updated_at=datetime('now');
